  "findings": [
    {
      "rule_id": "sql-injection",
      "severity": "error",
      "location": "app/db.py:20",
      "evidence": "sql = f\"SELECT id, name, email FROM users WHERE name = '{name}'\""
    },
    {
      "rule_id": "sql-injection",
      "severity": "error",
      "location": "app/db.py:33",
      "evidence": "sql = f\"SELECT id, name, email FROM users WHERE email LIKE '%{domain}'\""
    },
    {
      "rule_id": "bare-except",
      "severity": "error",
      "location": "app/db.py:24",
      "evidence": "except Exception:  # Seeded defect: bare except swallows everything.\n    return None"
    },
    {
      "rule_id": "bare-except",
      "severity": "error",
      "location": "app/importer.py:21",
      "evidence": "except Exception:\n    pass"
    },
    {
      "rule_id": "bare-except",
      "severity": "error",
      "location": "app/legacy_utils.py:32",
      "evidence": "except Exception:\n    pass"
    },
    {
      "rule_id": "bare-except",
      "severity": "error",
      "location": "app/main.py:12",
      "evidence": "except Exception:\n    pass"
    },
    {
      "rule_id": "unsafe-deserialization",
      "severity": "error",
      "location": "app/importer.py:9",
      "evidence": "payload = pickle.loads(fh.read())"
    },
    {
      "rule_id": "unsafe-deserialization",
      "severity": "error",
      "location": "app/legacy_utils.py:10",
      "evidence": "return pickle.loads(fh.read())"
    },
    {
      "rule_id": "unsafe-deserialization",
      "severity": "error",
      "location": "app/legacy_utils.py:16",
      "evidence": "data = pickle.loads(fh.read())"
    },
    {
      "rule_id": "hardcoded-secret",
      "severity": "error",
      "location": "app/payments.py:4",
      "evidence": "PAYMENTS_API_KEY = \"sk-legacy-payments-6c2e8a4f1b\""
    },
    {
      "rule_id": "debug-print",
